#!/usr/bin/env bash
# Create the testnet contract and treasury accounts through the NEAR faucet.
# Keys are generated by near-cli-rs and saved to its keychain, never to this repo.
set -euo pipefail

. "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/_common.sh"

case "$NEAR_NETWORK" in
    testnet*) ;;
    *) die "faucet account creation is testnet-only (NEAR_NETWORK=$NEAR_NETWORK)" ;;
esac

require_cmd "$NEAR_CLI"
require_var CONTRACT_ACCOUNT_ID
require_var TREASURY_ACCOUNT_ID

create_account() {
    local account_id="$1"
    if account_exists "$account_id"; then
        say "$account_id already exists; leaving it unchanged"
        return
    fi
    say "Creating $account_id through the testnet faucet"
    "$NEAR_CLI" account create-account sponsor-by-faucet-service "$account_id" \
        autogenerate-new-keypair save-to-keychain network-config "$NEAR_NETWORK" create
}

create_account "$CONTRACT_ACCOUNT_ID"
create_account "$TREASURY_ACCOUNT_ID"

if [[ "$OWNER_ACCOUNT_ID" != "$CONTRACT_ACCOUNT_ID" && "$OWNER_ACCOUNT_ID" != "$TREASURY_ACCOUNT_ID" ]]; then
    if account_exists "$OWNER_ACCOUNT_ID"; then
        say "$OWNER_ACCOUNT_ID already exists; leaving it unchanged"
    elif [[ "${CREATE_OWNER_ACCOUNT:-0}" == "1" ]]; then
        create_account "$OWNER_ACCOUNT_ID"
    else
        die "owner account $OWNER_ACCOUNT_ID does not exist; set CREATE_OWNER_ACCOUNT=1 to create it with the faucet"
    fi
fi

say "Accounts are ready. Keys are in the near-cli-rs keychain, not in this repository."
say "Next: ./scripts/build.sh && ./scripts/deploy.sh"
